import{_ as a,c as t,o as e,a2 as o}from"./chunks/framework.BX_emVE_.js";const u=JSON.parse('{"title":"关于徽章","description":"","frontmatter":{},"headers":[],"relativePath":"credential/about-badge.md","filePath":"credential/about-badge.md"}'),r={name:"credential/about-badge.md"},n=o('<h1 id="关于徽章" tabindex="-1">关于徽章 <a class="header-anchor" href="#关于徽章" aria-label="Permalink to &quot;关于徽章&quot;">​</a></h1><p>徽章是记录在火石凭证中一种纪念方式，用于纪念某些重要的时刻。</p><h2 id="如何获得徽章" tabindex="-1">如何获得徽章？ <a class="header-anchor" href="#如何获得徽章" aria-label="Permalink to &quot;如何获得徽章？&quot;">​</a></h2><p>我们会在许多平台发放徽章兑换码，您可以在微信公众号中关注推文，或者我们的其他网站寻找兑换码，您可以在其中发现许多兑换码。</p><h2 id="徽章分类" tabindex="-1">徽章分类 <a class="header-anchor" href="#徽章分类" aria-label="Permalink to &quot;徽章分类&quot;">​</a></h2><p>每一个时刻都值得被记录，但有些时刻也十分值得纪念。为了区分这些更值得纪念的时刻，我们对徽章进行了分类。徽章分为<strong>普通徽章</strong>以及<strong>限定徽章</strong>。</p><p>普通徽章<strong>不限时获得</strong>，可随时兑换，没有截止期。普通徽章呈现的是银白色，故事或简介部分情况下也可能会更长或更短。</p><p>限定徽章<strong>限时兑换</strong>，需要使用兑换码进行兑换，截止时间一般为半个月至一个月，故事会更长，同时查看详情时会携带一张Emoji图片，以彰显限定徽章的特色。 <img src="https://static.turboflint.cn/image/docs-01.jpg" alt="限定徽章介绍示例"></p><h2 id="如何兑换已截止的徽章" tabindex="-1">如何兑换已截止的徽章？ <a class="header-anchor" href="#如何兑换已截止的徽章" aria-label="Permalink to &quot;如何兑换已截止的徽章？&quot;">​</a></h2><p>部分已截止的徽章可以在例如周年活动、新项目上线、小彩蛋或大活动期间再次开放兑换。</p><p>这些返场徽章<strong>不包含纪念日类</strong>，如新年或周年徽章。</p><p>您可以关注微信公众号，关注最新推文，期待更多徽章返场兑换。</p>',12),s=[n];function i(c,d,l,p,h,_){return e(),t("div",null,s)}const b=a(r,[["render",i]]);export{u as __pageData,b as default};
